import{_ as t,c as s,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"易雅原序","description":"周易輯聞 - 易雅原序","frontmatter":{"title":"易雅原序","description":"周易輯聞 - 易雅原序"},"headers":[],"relativePath":"classics/jiwen/008.md","filePath":"classics/jiwen/008.md"}'),i={name:"classics/jiwen/008.md"};function c(o,a,l,d,p,m){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易雅原序",tabindex:"-1"},[n("易雅原序 "),e("a",{class:"header-anchor",href:"#易雅原序","aria-label":"Permalink to “易雅原序”"},"​")],-1),e("p",null,"爾雅，訓詁之書也。目張而匯聚，讀之事義物理秩然在前。富哉書也，經之翼乎！厥後廣雅、博雅、埤雅，雖依放為書，大槩於道無所益。易雅之作，則異於是。易，變易也。卦殊其義，爻異其旨，萬變畢陳，眾理叢載。學者如乍入清廟，目衒於尊彝幣玉，體煩於升降盥奠，耳亂於鐘鼓磬簫。凡禮之文，樂之節，且不暇品名，況能因之以知其實乎？又若泛滄海而罔識鄉往之方，遊建章而不知出入之會。汝梅嘗病焉，乃復熟畫辭而為此書，庶幾緣是指入易之迷津，求體易之實用。或曰：「子何沈錮辭畫，不能融渾希微若是哉？」餘曰：「程子論為學之害曰：昔之害，乘其迷暗；今之害，因其高明。自謂之窮神知化，實則不足以開物成務；言為無不周徧，實則外於倫理。嗟夫！淺深非二水，體用非二物，精粗無二理也。易之為書，言近而指遠，不知言何以知其指？通乎近，則遠固在是，儻慕遠而失諸近，吾知兩失之而已爾。世或外辭畫以求易，則此書為贅，否則不易吾言矣。程子之論，真為學之大閒歟！」汴水趙汝梅敘。易雅原序。",-1)])])}const h=t(i,[["render",c]]);export{f as __pageData,h as default};
